using System.Linq;
using FluentAssertions;
using MessagePack.SourceGenerator.Analyzers;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Diagnostics;
using Microsoft.CodeAnalysis.Testing;

namespace Receipts.GeneratedTests;

public class RecordPrimaryCtorNullKeyDiagnosticTests
{
    private readonly ITestOutputHelper logger;

    public RecordPrimaryCtorNullKeyDiagnosticTests(ITestOutputHelper logger)
    {
        this.logger = logger;
    }

    [Fact]
    public async Task NullKeyOnRecordPrimaryConstructorPropertyIsStillReported()
    {
        string source = """
            using MessagePack;

            namespace App
            {
                [MessagePackObject]
                public partial record Cmd([property: Key((string)null)] string Scope);
            }
            """;

        ImmutableArray<MetadataReference> frameworkRefs = await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        var references = frameworkRefs.AddRange(ReferencesHelper.GetReferences(ReferencesSet.MessagePack));

        CSharpCompilation compilation = CSharpCompilation.Create(
            "App",
            new[] { CSharpSyntaxTree.ParseText(source, new CSharpParseOptions(LanguageVersion.Latest)) },
            references,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        var compileErrors = compilation.GetDiagnostics().Where(d => d.Severity == DiagnosticSeverity.Error).ToList();
        foreach (var d in compileErrors)
        {
            this.logger.WriteLine(d.ToString());
        }

        compileErrors.Should().BeEmpty();

        ImmutableArray<DiagnosticAnalyzer> analyzers = ImmutableArray.Create<DiagnosticAnalyzer>(new MsgPack00xMessagePackAnalyzer());
        ImmutableArray<Diagnostic> diagnostics = await compilation.WithAnalyzers(analyzers).GetAllDiagnosticsAsync();
        foreach (var d in diagnostics)
        {
            this.logger.WriteLine(d.ToString());
        }

        diagnostics.Should().NotContain(d => d.Id == "AD0001");
        diagnostics.Should().Contain(d => d.Id.StartsWith("MsgPack") && d.GetMessage().Contains("Scope"));
    }
}
